from collections import deque
for _ in range(int(input())):
	(n, k) = map(int, input().split())
	a = list(map(int, input().split()))
	q = deque([])
	if n == k:
		print(0)
	else:
		for i in range(k + 1):
			while q and a[i] <= a[q[-1]]:
				q.pop()
			q.append(i)
		for i in range(k + 1, n):
			a[i] += a[q[0]]
			while q and q[0] <= i - (k + 1):
				q.popleft()
			while q and a[i] <= a[q[-1]]:
				q.pop()
			q.append(i)
		print(str(min(a[n - k - 1:n])))
